create or replace function aria_memory.confidence_from_evidence(p_successes integer,p_failures integer,p_base numeric default .5) returns numeric language sql immutable set search_path='' as $$ select least(.99,greatest(.01,case when coalesce(p_successes,0)+coalesce(p_failures,0)=0 then p_base else (coalesce(p_successes,0)+1.0)/(coalesce(p_successes,0)+coalesce(p_failures,0)+2.0) end)); $$;
create or replace function aria_memory.recalculate_confidence(p_memory_id uuid) returns numeric language plpgsql security definer set search_path='' as $$ declare v_s integer; v_f integer; v_c numeric; begin select count(*) filter(where payload->>'result'='success'),count(*) filter(where payload->>'result'='failure') into v_s,v_f from aria_memory.memory_events where memory_id=p_memory_id and event_type='verified'; v_c:=aria_memory.confidence_from_evidence(v_s,v_f,(select confidence from aria_memory.memory_items where memory_id=p_memory_id)); update aria_memory.memory_items set confidence=v_c,updated_at=now() where memory_id=p_memory_id; insert into aria_memory.memory_events(memory_id,event_type,payload) values(p_memory_id,'updated',jsonb_build_object('confidence',v_c,'successes',v_s,'failures',v_f)); return v_c; end; $$;
revoke all on function aria_memory.confidence_from_evidence(integer,integer,numeric),aria_memory.recalculate_confidence(uuid) from public,anon,authenticated;
grant execute on function aria_memory.confidence_from_evidence(integer,integer,numeric),aria_memory.recalculate_confidence(uuid) to service_role;

create or replace function aria_memory.compile_skill_for_goal(p_goal text) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; v_count integer; v_content text; v_hash text; begin if p_goal is null or length(trim(p_goal))=0 then raise exception 'goal_required'; end if; select count(*) into v_count from aria_memory.memory_items where memory_type='lesson' and status='active' and metadata->>'reusable_candidate'='true' and metadata->>'goal'=p_goal and confidence>=.9; if v_count<3 then return null; end if; v_content:='Procedural skill compiled from '||v_count::text||' verified successful mission reflections for goal: '||trim(p_goal)||'. Reuse the validated mission pattern, preserve governance, verify each result, and replan when observations diverge.'; v_hash:=encode(extensions.digest(v_content,'sha256'),'hex'); insert into aria_memory.memory_items(memory_type,title,content,content_hash,source_type,provenance,metadata,confidence,importance,salience) values('skill','Compiled skill: '||left(trim(p_goal),160),v_content,v_hash,'aria',jsonb_build_object('compiler','skill-compiler-v1','evidence_count',v_count),jsonb_build_object('goal',trim(p_goal),'evidence_count',v_count,'compiled',true,'version','v1'),least(.99,.75+v_count*.05),.95,.95) on conflict(content_hash) do update set confidence=least(.99,.75+v_count*.05),metadata=jsonb_set(aria_memory.memory_items.metadata,'{evidence_count}',to_jsonb(v_count),true),updated_at=now() returning memory_id into v_id; insert into aria_memory.memory_events(memory_id,event_type,payload) values(v_id,'promoted',jsonb_build_object('compiler','skill-compiler-v1','evidence_count',v_count,'goal',p_goal)); insert into aria_memory.memory_relations(from_memory_id,to_memory_id,relation_type,strength,provenance) select v_id,m.memory_id,'implements',m.confidence,jsonb_build_object('compiler','skill-compiler-v1') from aria_memory.memory_items m where m.memory_type='lesson' and m.status='active' and m.metadata->>'reusable_candidate'='true' and m.metadata->>'goal'=p_goal and m.confidence>=.9 on conflict(from_memory_id,to_memory_id,relation_type) do nothing; return v_id; end; $$;
revoke all on function aria_memory.compile_skill_for_goal(text) from public,anon,authenticated; grant execute on function aria_memory.compile_skill_for_goal(text) to service_role;

create table if not exists aria_memory.world_entities(entity_id uuid primary key default gen_random_uuid(),entity_type text not null check(entity_type in('person','system','resource','project','tool','model','provider','device','mission','concept')),canonical_name text not null,status text not null default 'active' check(status in('active','inactive','unknown','archived')),attributes jsonb not null default '{}',confidence numeric(5,4) not null default .5 check(confidence between 0 and 1),source_ref text,provenance jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(entity_type,canonical_name));
create table if not exists aria_memory.world_relations(relation_id uuid primary key default gen_random_uuid(),from_entity_id uuid not null references aria_memory.world_entities(entity_id) on delete cascade,to_entity_id uuid not null references aria_memory.world_entities(entity_id) on delete cascade,relation_type text not null,attributes jsonb not null default '{}',confidence numeric(5,4) not null default .5 check(confidence between 0 and 1),valid_from timestamptz not null default now(),valid_until timestamptz,source_ref text,provenance jsonb not null default '{}',created_at timestamptz not null default now(),unique(from_entity_id,to_entity_id,relation_type));
create table if not exists aria_memory.world_events(event_id bigint generated always as identity primary key,entity_id uuid references aria_memory.world_entities(entity_id) on delete cascade,event_type text not null,payload jsonb not null default '{}',created_at timestamptz not null default now());
create index if not exists world_entities_type_name_idx on aria_memory.world_entities(entity_type,canonical_name); create index if not exists world_relations_from_idx on aria_memory.world_relations(from_entity_id); create index if not exists world_relations_to_idx on aria_memory.world_relations(to_entity_id); create index if not exists world_events_entity_idx on aria_memory.world_events(entity_id,created_at desc);
alter table aria_memory.world_entities enable row level security; alter table aria_memory.world_relations enable row level security; alter table aria_memory.world_events enable row level security; revoke all on aria_memory.world_entities,aria_memory.world_relations,aria_memory.world_events from anon,authenticated; grant select,insert,update,delete on aria_memory.world_entities,aria_memory.world_relations,aria_memory.world_events to service_role;
create or replace function aria_memory.upsert_world_entity(p_entity_type text,p_canonical_name text,p_status text default 'active',p_attributes jsonb default '{}',p_confidence numeric default .5,p_source_ref text default null,p_provenance jsonb default '{}') returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; begin insert into aria_memory.world_entities(entity_type,canonical_name,status,attributes,confidence,source_ref,provenance) values(p_entity_type,trim(p_canonical_name),p_status,coalesce(p_attributes,'{}'),p_confidence,p_source_ref,coalesce(p_provenance,'{}')) on conflict(entity_type,canonical_name) do update set status=excluded.status,attributes=aria_memory.world_entities.attributes||excluded.attributes,confidence=greatest(aria_memory.world_entities.confidence,excluded.confidence),source_ref=coalesce(excluded.source_ref,aria_memory.world_entities.source_ref),provenance=aria_memory.world_entities.provenance||excluded.provenance,updated_at=now() returning entity_id into v_id; insert into aria_memory.world_events(entity_id,event_type,payload) values(v_id,'upserted',jsonb_build_object('entity_type',p_entity_type,'canonical_name',p_canonical_name)); return v_id; end; $$;
create or replace function aria_memory.link_world_entities(p_from uuid,p_to uuid,p_relation_type text,p_confidence numeric default .5,p_attributes jsonb default '{}',p_source_ref text default null,p_provenance jsonb default '{}') returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; begin insert into aria_memory.world_relations(from_entity_id,to_entity_id,relation_type,confidence,attributes,source_ref,provenance) values(p_from,p_to,p_relation_type,p_confidence,coalesce(p_attributes,'{}'),p_source_ref,coalesce(p_provenance,'{}')) on conflict(from_entity_id,to_entity_id,relation_type) do update set confidence=greatest(aria_memory.world_relations.confidence,excluded.confidence),attributes=aria_memory.world_relations.attributes||excluded.attributes,provenance=aria_memory.world_relations.provenance||excluded.provenance returning relation_id into v_id; return v_id; end; $$;
revoke all on function aria_memory.upsert_world_entity(text,text,text,jsonb,numeric,text,jsonb),aria_memory.link_world_entities(uuid,uuid,text,numeric,jsonb,text,jsonb) from public,anon,authenticated; grant execute on function aria_memory.upsert_world_entity(text,text,text,jsonb,numeric,text,jsonb),aria_memory.link_world_entities(uuid,uuid,text,numeric,jsonb,text,jsonb) to service_role;
